test("remainder to smallest scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "grace-B", "5");
  await ui.setSetting(pg_uma, "proof-threshold-C", "0.50");
  await ui.setSetting(pg_uma, "pot", "100.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "tags": "b, a"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "20", "tags": "b, a"}));
  expect(await ui.inlineGrade(pg_uma, p_cam, "C")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33", "from": "2026-03-16"})).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  await ui.sortBy(pg_uma, "name");
  expect(await ui.statementAsOf(pg_uma, p_cam, "2026-03-20")).toBe(false);
  expect(await ui.hold(pg_uma, p_ada, {"from": "2026-02-10"})).toBe(true);
  await ui.setToday(pg_uma, "2026-05-09");
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("my-due-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-overdue-total")).toHaveText("");
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25"}));
  expect(await ui.claimEditOpen(pg_uma, c_cam_0)).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimEditOpen(pg_vic, c_cam_0)).toBe(false);
  await ui.refresh(pg_uma);
  expect(await ui.claimEditSave(pg_uma, c_cam_0, {"amount": "0.04"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  const c_cam_1 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "1.00", "date": "2026-03-09", "note": "n", "ref": "R-1", "tags": "b,a,a"}));
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  const c_cam_2 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "4.00"}));
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.04");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-due")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.04");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");

